import java.util.*;

public class PermutationGenerator {

    public static void getPermutations(List<Character> letters, int index, Set<String> result) {
        if (index == letters.size()) {
            result.add(new String(letters.toArray(new Character[0])));
        } else {
            for (int i = index; i < letters.size(); i++) {
                Collections.swap(letters, i, index);
                getPermutations(letters, index + 1, result);
                Collections.swap(letters, i, index);
            }
        }
    }

    public static List<String> getPermutations(List<Character> letters) {
        Set<String> result = new LinkedHashSet<>(); // Using LinkedHashSet to maintain order
        getPermutations(letters, 0, result);
        return new ArrayList<>(result);
    }
}
