### Step 3: Implement the Particle Filter Node

Edit the `src` folder in your package and add a file called `particle_filter_node.cpp`.

```cpp
#include <rclcpp/rclcpp.hpp>
#include <geometry_msgs/msg/pose_stamped.hpp>
#include <sensor_msgs/msg/laser_scan.hpp>
#include <random>
#include <vector>

class ParticleFilterNode : public rclcpp::Node {
public:
    ParticleFilterNode()
        : Node("particle_filter_node"), num_particles_(100), weight_sum_(0.0) {
        RCLCPP_INFO(this->get_logger(), "Particle Filter Node started.");

        pose_sub_ = this->create_subscription<geometry_msgs::msg::PoseStamped>(
            "robot_pose", 10, std::bind(&ParticleFilterNode::poseCallback, this, std::placeholders::_1));

        scan_sub_ = this->create_subscription<sensor_msgs::msg::LaserScan>(
            "scan", 10, std::bind(&ParticleFilterNode::laserScanCallback, this, std::placeholders::_1));

        particles_pub_ = this->create_publisher<std_msgs::msg::Float64MultiArray>("particles", 10);
    }

private:
    int num_particles_;
    double weight_sum_;
    rclcpp::Subscription<geometry_msgs::msg::PoseStamped>::SharedPtr pose_sub_;
    rclcpp::Subscription<sensor_msgs::msg::LaserScan>::SharedPtr scan_sub_;
    rclcpp::Publisher<std_msgs::msg::Float64MultiArray>::SharedPtr particles_pub_;

    void poseCallback(const geometry_msgs::msg::PoseStamped::SharedPtr msg) {
        // Update the initial positions of the particles based on the robot's pose
        for (auto &particle : particles_) {
            particle.x = msg->pose.position.x;
        }
    }

    void laserScanCallback(const sensor_msgs::msg::LaserScan::SharedPtr msg) {
        // Resample particles based on the laser scan data
        resampleParticles(msg);
    }

